    unsigned char _pad[4];
    long Family;                                         // +4
    unsigned long Stepping;                              // +8
    long Model;                                          // +0xc
    const char* GetCentaurModelName() const;
};

const char* CCpuInfo::GetCentaurModelName() const
{
    switch (Family) {
    case 5:
        if (Model == 4)
            return "WinChip C6";
        break;
    case 6:
        if (Model == 6)
